// src/clock.js: a plain module that hot-swaps itself
let timer = setInterval(() => {
  document.title = new Date().toLocaleTimeString();
}, 1000);

export function format(d) {
  return d.toISOString();
}

if (import.meta.hot) {
  // clean up side effects of this version before the new one runs
  import.meta.hot.dispose(() => clearInterval(timer));
  // accept updates: no full page reload when this file changes
  import.meta.hot.accept((newModule) => {
    console.log("clock updated", typeof newModule?.format);
  });
}

