// vite.config.js
import { defineConfig } from "vite";

function buildInfo() {
  const id = "virtual:build-info";
  return {
    name: "build-info",
    resolveId(source) {
      if (source === id) return "\0" + id;         // virtual module id
    },
    load(resolved) {
      if (resolved === "\0" + id) {
        return `export default ${JSON.stringify({ builtAt: new Date().toISOString() })};`;
      }
    },
    transformIndexHtml(html) {
      return html.replace("</head>", `<meta name="generator" content="vite"></head>`);
    },
  };
}

export default defineConfig({ plugins: [buildInfo()] });
// in app code:  import info from "virtual:build-info";  info.builtAt

// server.js (development): Express + Vite in middleware mode
import express from "express";
import fs from "node:fs/promises";
import { createServer } from "vite";

const app = express();
const vite = await createServer({ server: { middlewareMode: true }, appType: "custom" });
app.use(vite.middlewares);                       // assets, HMR, transforms

app.use("*all", async (req, res) => {
  let html = await fs.readFile("index.html", "utf8");
  html = await vite.transformIndexHtml(req.originalUrl, html);
  const { render } = await vite.ssrLoadModule("/src/entry-server.js");
  const appHtml = await render(req.originalUrl);
  res.type("html").send(html.replace("<!--app-html-->", appHtml));
});
app.listen(5173);

